{
  "policy_type": "rules",
  "name": "policy_ep_40",
  "rules": [
    {"if": [{"feature": "theta", "op": ">", "value": 0.1}], "then": 1},
    {"if": [{"feature": "theta", "op": "<", "value": -0.1}], "then": 0},
    {"if": [{"feature": "x", "op": ">", "value": 0.5}], "then": 0},
    {"if": [{"feature": "x", "op": "<", "value": -0.5}], "then": 1}
  ],
  "default_action": 0,
  "notes": "This initial policy is designed to emphasize balancing by primarily responding to the pole angle (theta). The rules are set to push the cart in the direction that counteracts the pole's tilt. Additionally, boundaries for cart position (x) are introduced to prevent the cart from moving too far to the sides, which could lead to a fail state. Since no previous policies exist, this serves as a baseline for further iterations."
}

